"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { Button as BaseButton } from "@base-ui/react/button";

import { mergeClassName } from "../shared/merge-class-name.js";
import { styles } from "./icon-button.stylex.js";

export type IconButtonSize = "compact" | "default";
export type IconButtonVariant = "secondary" | "ghost";

export interface IconButtonProps extends Omit<
  BaseButton.Props,
  "aria-label" | "aria-pressed" | "children" | "className" | "disabled"
> {
  "aria-label": string;
  children: React.ReactElement<{
    "aria-hidden"?: boolean;
    focusable?: string;
    style?: React.CSSProperties;
  }>;
  className?: BaseButton.Props["className"];
  disabled?: boolean;
  selected?: boolean;
  size?: IconButtonSize;
  variant?: IconButtonVariant;
}

export const IconButton = React.forwardRef<HTMLElement, IconButtonProps>(function IconButton(
  {
    "aria-label": ariaLabel,
    children,
    className,
    disabled,
    nativeButton,
    render,
    selected,
    size = "compact",
    variant = "secondary",
    ...props
  },
  ref,
) {
  const generated = stylex.props(
    styles.root,
    styles.rounded,
    styles[size],
    styles[variant],
  ).className;
  const icon = React.cloneElement(children, {
    "aria-hidden": true,
    focusable: "false",
    style: { ...children.props.style, height: "100%", width: "100%" },
  });

  return (
    <BaseButton
      {...props}
      aria-label={ariaLabel}
      aria-pressed={selected === undefined ? undefined : selected}
      className={mergeClassName(generated, className)}
      data-selected={selected ? "true" : undefined}
      data-size={size}
      data-slot="icon-button"
      data-variant={variant}
      disabled={disabled}
      nativeButton={nativeButton ?? render === undefined}
      ref={ref}
      render={render}
    >
      <span aria-hidden="true" data-slot="icon-button-icon" {...stylex.props(styles.icon)}>
        {icon}
      </span>
      <span
        aria-hidden="true"
        data-slot="icon-button-state-layer"
        {...stylex.props(styles.stateLayer)}
      />
    </BaseButton>
  );
});

import * as stylex from "@stylexjs/stylex";

import { tokens } from "../tokens.stylex.js";

export const stateLayer = stylex.defineVars({
  background: "transparent",
  border: "transparent",
});

export const styles = stylex.create({
  root: {
    [stateLayer.background]: {
      default: null,
      ":active": tokens.colorInteractionPressedOverlay,
      '[data-visual-state="pressed"]': tokens.colorInteractionPressedOverlay,
    },
    [stateLayer.border]: {
      default: null,
      ":focus-visible": tokens.colorFocusRing,
      '[data-visual-state="focus-visible"]': tokens.colorFocusRing,
    },
    alignItems: "center",
    borderStyle: "none",
    borderWidth: 0,
    boxSizing: "border-box",
    cursor: {
      default: "pointer",
      ":disabled": "default",
      '[data-visual-state="disabled"]': "default",
    },
    display: "inline-flex",
    flexShrink: 0,
    justifyContent: "center",
    outline: "none",
    opacity: {
      default: tokens.opacityEnabled,
      ":disabled": tokens.opacityDisabled,
      '[data-visual-state="disabled"]': tokens.opacityDisabled,
    },
    padding: 0,
    position: "relative",
    transitionDuration: "120ms",
    transitionProperty: "background-color, color, opacity",
    transitionTimingFunction: "ease-out",
  },
  compact: {
    height: tokens.sizeIconButtonCompact,
    width: tokens.sizeIconButtonCompact,
  },
  default: {
    height: tokens.sizeIconButtonDefault,
    width: tokens.sizeIconButtonDefault,
  },
  rounded: {
    borderRadius: tokens.radiusRounded,
  },
  secondary: {
    backgroundColor: {
      default: tokens.colorSurfaceTranslucent,
      ":hover": tokens.colorSurfaceLevel3,
      ":active": tokens.colorSurfaceLevel3,
      ":disabled": tokens.colorSurfaceTranslucent,
      '[data-selected="true"]': tokens.colorSurfaceTranslucent,
      '[data-visual-state="hover"]': tokens.colorSurfaceLevel3,
      '[data-visual-state="pressed"]': tokens.colorSurfaceLevel3,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-translucent, rgba(0, 0, 0, 0.08))",
    color: tokens.colorContentPrimary,
  },
  ghost: {
    backgroundColor: {
      default: "transparent",
      ":hover": tokens.colorSurfaceQuaternary,
      ":active": tokens.colorSurfaceQuaternary,
      ":disabled": "transparent",
      '[data-selected="true"]': tokens.colorSurfaceTranslucent,
      '[data-visual-state="hover"]': tokens.colorSurfaceQuaternary,
      '[data-visual-state="pressed"]': tokens.colorSurfaceQuaternary,
    },
    boxShadow: "inset 0 0 0 0.5px var(--color-border-transparent, transparent)",
    color: tokens.colorContentTertiary,
  },
  icon: {
    alignItems: "center",
    display: "inline-flex",
    flexShrink: 0,
    height: tokens.sizeIconDefault,
    justifyContent: "center",
    pointerEvents: "none",
    width: tokens.sizeIconDefault,
  },
  stateLayer: {
    backgroundColor: stateLayer.background,
    borderColor: stateLayer.border,
    borderRadius: "inherit",
    borderStyle: "solid",
    borderWidth: "1px",
    boxSizing: "border-box",
    inset: 0,
    pointerEvents: "none",
    position: "absolute",
  },
});

export type ClassName<State> = string | ((state: State) => string | undefined);

export function mergeClassName<State>(
  generated?: string,
  className?: ClassName<State>,
): ClassName<State> {
  if (typeof className === "function") {
    return (state) => [generated, className(state)].filter(Boolean).join(" ");
  }
  return [generated, className].filter(Boolean).join(" ");
}
